fn mat_mul(a: &[Vec<f64>], b: &[Vec<f64>]) -> Option<Vec<Vec<f64>>> {
    // Check that both matrices have at least one row
    if a.is_empty() || b.is_empty() {
        return None;
    }

    // Get dimensions
    let rows_a = a.len();
    let cols_a = a[0].len();
    let rows_b = b.len();
    let cols_b = b[0].len();

    // Check that all rows in a have the same length (cols_a)
    for row in a.iter().skip(1) {
        if row.len() != cols_a {
            return None;
        }
    }

    // Check that all rows in b have the same length (cols_b)
    for row in b.iter().skip(1) {
        if row.len() != cols_b {
            return None;
        }
    }

    // Check compatibility: cols_a must equal rows_b
    if cols_a != rows_b {
        return None;
    }

    // Initialize result matrix with zeros: rows_a x cols_b
    let mut result = vec![vec![0.0; cols_b]; rows_a];

    // Perform multiplication
    for i in 0..rows_a {
        for j in 0..cols_b {
            let mut sum = 0.0;
            for k in 0..cols_a {
                sum += a[i][k] * b[k][j];
            }
            result[i][j] = sum;
        }
    }

    Some(result)
}
